/** @format */

import billing from "../../../media/products/billing.svg";
import eCommerce from "../../../media/products/eCommerce.svg";
import erp from "../../../media/products/erp.svg";
import fund from "../../../media/products/fund.svg";
import hotel from "../../../media/products/hotel.svg";
import inventory from "../../../media/products/inventory.svg";
import location from "../../../media/products/location.svg";
import payroll from "../../../media/products/payroll.svg";

const data = [
  {
    id: 1,
    img: payroll,
    title: "Payroll System",
    detailPage: "payroll-system",
    description:
      "Suffix Payroll will help you to automate and streamline all of your HR services",
  },
  {
    id: 2,
    img: billing,
    title: "Interconnect Billing",
    detailPage: "interconnect-billing",
    description:
      "It will allow business optimization and help in achieving increased operational efficiency and network profitability",
  },
  {
    id: 3,
    img: eCommerce,
    title: "E-Commerce",
    detailPage: "e-commerce",
    description:
      "We offer full-cycle retail and e-commerce app solutions to both B2B and B2C customers, based on their specific requirements.",
  },
  {
    id: 4,
    img: erp,
    title: "Rupantor ERP",
    detailPage: "rupantor-erp",
    description:
      "Rupantor ERP will integrate all of the processes needed to run your business.",
  },
  {
    id: 5,
    img: fund,
    title: "Provident Fund ",
    detailPage: "provident-fund",
    description:
      "An advanced way to handle your employee’s funding management with our PF Software.",
  },
  {
    id: 6,
    img: hotel,
    title: "Hotel Booking System",
    detailPage: "hotel-booking-system",
    description:
      "We provide the cloud based most user friendly and cost effective hotel booking management system.",
  },
  {
    id: 7,
    img: inventory,
    title: "Rupantor Inventory",
    detailPage: "rupantor-inventory",
    description:
      "Our Inventory Management system will manage your cash flow, reduce cost and maximize profits",
  },
  {
    id: 8,
    img: location,
    title: "Filed Force Management ",
    detailPage: "field-force-management",
    description:
      "With Suffix Field force you can move a lot faster and keep adapting to your customers needs.",
  },
];

export default data;
